A.agb=new B.al("prednisolone","Prednisolone",A.bcn,"\u0e40\u0e1e\u0e23\u0e14\u0e19\u0e34\u0e42\u0e0b\u0e42\u0e25\u0e19",A.lU,A.z,A.bfS,null,A.a0,A.z,null,!1,!1,!1,!1,"Corticosteroid",null,A.b9o,"Short course (3-5 days) for asthma exacerbation. Monitor blood glucose. Taper if >7 days use.","\u0e43\u0e0a\u0e49\u0e23\u0e30\u0e22\u0e30\u0e2a\u0e31\u0e49\u0e19 3-5 \u0e27\u0e31\u0e19\u0e2a\u0e33\u0e2b\u0e23\u0e31\u0e1a\u0e2b\u0e2d\u0e1a\u0e2b\u0e37\u0e14\u0e01\u0e33\u0e40\u0e23\u0e34\u0e1a \u0e23\u0e30\u0e27\u0e31\u0e07\u0e19\u0e49\u0e33\u0e15\u0e32\u0e25\u0e2a\u0e39\u0e07 \u0e16\u0e49\u0e32\u0e43\u0e0a\u0e49\u0e40\u0e01\u0e34\u0e19 7 \u0e27\u0e31\u0e19\u0e15\u0e49\u0e2d\u0e07\u0e04\u0e48\u0e2d\u0e22\u0e46 \u0e25\u0e14\u0e42\u0e14\u0e2a","","",null,null,null,A.Z)
